CREATE TABLE `poker_player` (`Poker_Player_ID` DECIMAL(18,2), `People_ID` DECIMAL(18,2), `Final_Table_Made` DECIMAL(18,2), `Best_Finish` DECIMAL(18,2), `Money_Rank` DECIMAL(18,2), `Earnings` DECIMAL(18,2));
CREATE TABLE `people` (`People_ID` DECIMAL(18,2), `Nationality` VARCHAR(100), `Name` VARCHAR(100), `Birth_Date` VARCHAR(100), `Height` DECIMAL(18,2));
